/* eslint-disable @typescript-eslint/no-explicit-any */
import { isEqual } from 'lodash-es';
import React, { useCallback, useRef } from 'react';
import { useIntl } from 'react-intl';
import {
  ActionType,
  Column,
  Hooks,
  MetaBase,
  Row,
  TableInstance,
  TableState,
  actions,
} from 'react-table';

import { createSelectableRowCheckbox } from './SelectableRowCheckbox.js';
import { Checkbox } from '../../../forms/checkbox/Checkbox.js';
import { DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID } from '../../DataTable/constants.js';
import { dataTableMessages } from '../../DataTable/messages.js';
import { _convertColumn } from '../../types/table-type-mappings.js';
import { insertColumn } from '../../utils/column-utils.js';

export const useSelectableRowsActions = {
  /** Action for updating the selectedRowIds object. */
  updateSelectedRowIds: 'update-selected-row-ids',
};

actions.updateSelectedRowIds = useSelectableRowsActions.updateSelectedRowIds;

/** Default expand column definition which can be extended on */
export const TABLE_SELECTABLE_DEFAULT_COLUMN = {
  id: DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  header: ({
    getToggleAllPageRowsSelectedProps,
    updateSelectedRows,
  }: TableInstance) => {
    const { indeterminate, checked } = getToggleAllPageRowsSelectedProps();

    // Disables the rules of hooks, because `header` is spelled with a lowercase `h`
    // which is why the lint rule screams. Hooks can only be used in components
    // and component functions usually start with an uppercase letter. `header` in this case
    // is actually a component.
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const intl = useIntl();

    let headerCheckedState: boolean | 'indeterminate' = false;

    if (indeterminate) {
      headerCheckedState = 'indeterminate';
    } else if (checked === true) {
      headerCheckedState = true;
    }

    return (
      <Checkbox
        value={headerCheckedState}
        aria-label={
          checked
            ? intl.formatMessage(dataTableMessages.deselectAllPageRows)
            : intl.formatMessage(dataTableMessages.selectAllPageRows)
        }
        onChange={(checked: boolean) => updateSelectedRows(checked)}
      />
    );
  },
  width: 0,
  alignment: 'center' as 'center' | 'left',
  cell: createSelectableRowCheckbox(),
};

const additionalColumn = (columns: Column<any>[], table: MetaBase<any>) => {
  if (!table.instance.selectableRows) {
    return columns;
  }

  const INTERNAL_TABLE_SELECTABLE_DEFAULT_COLUMN = _convertColumn(
    TABLE_SELECTABLE_DEFAULT_COLUMN,
  );

  return insertColumn(
    columns,
    INTERNAL_TABLE_SELECTABLE_DEFAULT_COLUMN,
    [],
  ) as Column<any>[];
};

/**
 * ColumnDeps additional hook. Defines when the memoed columns should be updated.
 * Adds a dependency to be updated when selectableRows changes.
 */
function columnsDeps(deps: any[], { instance }: MetaBase<any>) {
  return [...deps, instance.selectableRows];
}

function reducer(state: TableState, action: ActionType) {
  if (action.type === actions.updateSelectedRowIds) {
    const { payload: updatedSelectedRowIds } = action;
    return {
      ...state,
      selectedRowIds: updatedSelectedRowIds,
    };
  } else {
    return state;
  }
}

/**
 * UseInstance hook for the selectable row.
 * Defining the necessary data and hooks and providing them via the instance.
 */
function useInstance(instance: TableInstance<any>) {
  const {
    setSelectedRows,
    onRowSelectionChange,
    page: currentPageRows,
    rowsById,
    state: { selectedRowIds: currentSelectedRowIds },
    controlledSelectableRows,
    data,
  } = instance;
  const prevPageRows = useRef(currentPageRows);
  const prevTableData = useRef(data);
  /**
   * Updates the selected rows and fires the change handler with the corresponding data.
   * Selecting/Deselecting all rows only affects the current page.
   *
   * @param selectedRowIds - either an object providing the selected row ids with the selection status or a boolean if all page rows should be selected/deselected
   */
  const updateSelectedRows = useCallback(
    (
      newSelectedRowIds: Record<string, boolean> | boolean,
      trigger: 'user' | 'internal' = 'user',
    ) => {
      // check if all rows on the current page should be selected/unselected
      if (typeof newSelectedRowIds === 'boolean') {
        let updatedPageRowSelection: {
          [p: string]: boolean | Record<string, boolean>;
        };
        if (trigger === 'internal') {
          // If the trigger is internal, update all rows in the TABLE to be selected/unselected
          updatedPageRowSelection = Object.fromEntries(
            Object.keys(rowsById).map((rowId) => [rowId, newSelectedRowIds]),
          );
        } else {
          // If the trigger is the user, only update all rows in the CURRENT PAGE to be selected/unselected
          updatedPageRowSelection = Object.fromEntries(
            currentPageRows.map((row) => [row.id, newSelectedRowIds]),
          );
        }
        newSelectedRowIds = {
          ...currentSelectedRowIds,
          ...updatedPageRowSelection,
        } as Record<string, boolean>;
      }

      const [selectedRows, selectedRowsData] = getSelectedRowsDataForEvent(
        newSelectedRowIds,
        rowsById,
      );
      setSelectedRows(selectedRows);

      onRowSelectionChange &&
        onRowSelectionChange(selectedRows, selectedRowsData, trigger);
    },
    [
      currentPageRows,
      currentSelectedRowIds,
      onRowSelectionChange,
      rowsById,
      setSelectedRows,
    ],
  );

  /**
   * Get the data for the onRowSelectionChange event.
   *
   * @param selectedRowIds - object providing the selected row ids with the selection status
   * @param rows - all rows of the table
   * @returns - object containing all selected rows and the corresponding row data
   */
  function getSelectedRowsDataForEvent(
    selectedRowIds: Record<string, boolean>,
    rows: Record<string, Row<any>>,
  ): [Record<string, boolean>, unknown[]] {
    const selectedRows: Record<string, boolean> = {};
    const data: unknown[] = [];
    Object.entries(selectedRowIds).forEach(([id, selected]) => {
      if (selected && rows[id]) {
        selectedRows[id] = selected;
        data.push(rows[id].original);
      }
    });
    return [selectedRows, data];
  }

  // for uncontrolled usage deselect all rows that are not displayed on the current page
  if (
    !isEqual(currentPageRows, prevPageRows.current) &&
    !controlledSelectableRows
  ) {
    // If the data has changed as well, reset all row selections
    if (!isEqual(data, prevTableData.current)) {
      updateSelectedRows(false, 'internal');
      prevTableData.current = data;
      // skip dispatching yet another update selection event if data has changed
    } else {
      const selectedRowIdsOnPage = {};
      currentPageRows.forEach((row) => {
        if (currentSelectedRowIds[row.id]) {
          selectedRowIdsOnPage[row.id] = true;
        }
      });
      // Dispatch an update selection event if selected rows don't match
      Object.keys(currentSelectedRowIds).length !==
        Object.keys(selectedRowIdsOnPage).length &&
        updateSelectedRows(selectedRowIdsOnPage, 'internal');
    }
    // If data has changed, an update selection event has already been dispatched.
    // Update the previous page rows regardless
    prevPageRows.current = currentPageRows;
  }

  Object.assign(instance, {
    updateSelectedRows,
  });
}

/** Table hook that enables selectable rows on tables. */
export function useSelectableRows<D extends Record<string, unknown>>(
  hooks: Hooks<D>,
): void {
  hooks.columns.push(additionalColumn);
  hooks.columnsDeps.push(columnsDeps);
  hooks.stateReducers.push(reducer);
  hooks.useInstance.push(useInstance);
}
useSelectableRows.pluginName = 'useSelectableRows';
